// Total de carros já gravados, para o contador continuar depois de reiniciar o Node-RED
const total = (msg.payload && msg.payload[0] && msg.payload[0].total) || 0;
flow.set('totalBanco', total);
node.status({ fill: 'blue', shape: 'dot', text: total + ' carros no banco' });
return null;

// Regras do semáforo
// Entrada: mensagens MQTT do ESP32 (fatec/semaforo/01/#), payload já em JSON.
// Saída 1 → dashboard (websocket /ws/semaforo)
// Saída 2 → comando de volta ao ESP32 (mqtt out)
// Saída 3 → gravações no banco SQLite (uma mensagem por INSERT)
const BASE = 'fatec/semaforo/01';
const T = {
    ultrasonic: BASE + '/sensor/ultrassonico',
    button: BASE + '/sensor/botao',
    state: BASE + '/estado',
    status: BASE + '/status',
    greenCmd: BASE + '/cmd/tempo_verde',
};
const DETECTION_CM = 50;       // abaixo disso há carro na faixa
const TOO_CLOSE_CM = 20;       // carro avançando sobre a faixa
const HEAVY_FLOW_PER_MIN = 8;  // fluxo intenso
const GREEN_NORMAL_S = 12;
const GREEN_EXTENDED_S = 16;
const WEAK_SIGNAL_DBM = -80;
const SAMPLE_MS = 5000;        // amostra para a tabela leituras

const mem = context.get('mem') || {
    distanceCm: 400, vehicleDetected: false, sessionCount: 0, detections: [],
    light: 'RED', remainingS: 0, durationS: 0, pedestrianRequest: false,
    online: false, wifiRssi: -100, uptimeS: 0, greenCmdS: GREEN_NORMAL_S,
    hasState: false, lastLight: null, alertCodes: [], lastSampleAt: 0,
};
const now = Date.now();
const ts = new Date(now).toISOString();
const p = (typeof msg.payload === 'object' && msg.payload) || {};
const db = [];
const sql = (topic, values) => db.push({ topic, payload: values });

switch (msg.topic) {
    case T.ultrasonic: {
        mem.distanceCm = Number(p.distanceCm ?? mem.distanceCm);
        const detected = mem.distanceCm < DETECTION_CM;
        if (detected && !mem.vehicleDetected) {   // borda de subida = carro novo
            mem.sessionCount += 1;
            mem.detections.push(now);
            sql('INSERT INTO veiculos (registrado_em, distancia_cm, estado_sinal) VALUES ($1, $2, $3)',
                [ts, mem.distanceCm, mem.light]);
        }
        mem.vehicleDetected = detected;
        break;
    }
    case T.button:
        if (p.pressed && !mem.pedestrianRequest) {
            sql('INSERT INTO pedidos_pedestre (registrado_em, estado_sinal) VALUES ($1, $2)', [ts, mem.light]);
        }
        if (p.pressed) mem.pedestrianRequest = true;
        break;
    case T.state:
        mem.light = p.light ?? mem.light;
        mem.remainingS = Number(p.remainingS ?? mem.remainingS);
        mem.durationS = Number(p.durationS ?? mem.durationS);
        mem.pedestrianRequest = Boolean(p.pedestrianRequest);
        mem.online = true;
        mem.hasState = true;
        break;
    case T.status:
        mem.online = Boolean(p.online);
        if (p.wifiRssi !== undefined) mem.wifiRssi = Number(p.wifiRssi);
        if (p.uptimeS !== undefined) mem.uptimeS = Number(p.uptimeS);
        break;
    default:
        return null; // ignora o próprio comando e outros tópicos
}

mem.detections = mem.detections.filter(t => now - t < 60000);
const vehiclesPerMin = mem.detections.length;

let mode = 'AUTOMATICO';
if (!mem.online) mode = 'ATENCAO';
else if (mem.pedestrianRequest) mode = 'PEDESTRE';
else if (vehiclesPerMin >= HEAVY_FLOW_PER_MIN) mode = 'FLUXO_INTENSO';

const alerts = [];
if (!mem.online) alerts.push({ level: 'critical', code: 'DISPOSITIVO_OFFLINE', message: 'ESP32 sem comunicação com o broker MQTT' });
if (mem.distanceCm < TOO_CLOSE_CM) alerts.push({ level: 'warning', code: 'VEICULO_PROXIMO', message: 'Veículo sobre a faixa (' + mem.distanceCm.toFixed(0) + ' cm)' });
if (mode === 'FLUXO_INTENSO') alerts.push({ level: 'warning', code: 'FLUXO_INTENSO', message: 'Fluxo intenso: verde estendido para ' + GREEN_EXTENDED_S + 's' });
if (mem.pedestrianRequest) alerts.push({ level: 'info', code: 'PEDESTRE_AGUARDANDO', message: 'Pedestre aguardando travessia' });
if (mem.online && mem.wifiRssi < WEAK_SIGNAL_DBM) alerts.push({ level: 'warning', code: 'SINAL_FRACO', message: 'Wi-Fi fraco no ESP32 (' + mem.wifiRssi + ' dBm)' });

// Histórico: troca de cor e alertas novos
if (mem.hasState && mem.light !== mem.lastLight) {
    mem.lastLight = mem.light;
    sql('INSERT INTO mudancas_sinal (registrado_em, estado, duracao_s, modo) VALUES ($1, $2, $3, $4)',
        [ts, mem.light, mem.durationS, mode]);
}
const codes = alerts.map(a => a.code);
alerts.filter(a => !mem.alertCodes.includes(a.code)).forEach(a =>
    sql('INSERT INTO alertas (registrado_em, nivel, codigo, mensagem) VALUES ($1, $2, $3, $4)',
        [ts, a.level, a.code, a.message]));
mem.alertCodes = codes;

if (mem.hasState && now - mem.lastSampleAt >= SAMPLE_MS) {
    mem.lastSampleAt = now;
    sql('INSERT INTO leituras (registrado_em, distancia_cm, carros_por_min, wifi_rssi, online) VALUES ($1, $2, $3, $4, $5)',
        [ts, mem.distanceCm, vehiclesPerMin, mem.wifiRssi, mem.online ? 1 : 0]);
}

// Automação: ajusta o tempo de verde do ESP32 conforme o fluxo
let command = null;
const wantedGreen = mode === 'FLUXO_INTENSO' ? GREEN_EXTENDED_S : GREEN_NORMAL_S;
if (mem.online && wantedGreen !== mem.greenCmdS) {
    mem.greenCmdS = wantedGreen;
    command = { topic: T.greenCmd, payload: { durationS: wantedGreen } };
    sql('INSERT INTO comandos (registrado_em, topico, payload) VALUES ($1, $2, $3)',
        [ts, T.greenCmd, JSON.stringify(command.payload)]);
}

context.set('mem', mem);
node.status({
    fill: mem.online ? 'green' : 'red', shape: 'dot',
    text: mem.light + ' ' + mem.remainingS + 's · ' + mem.distanceCm.toFixed(0) + ' cm · ' + mode,
});

let telemetry = null;
if (mem.hasState) {
    telemetry = {
        payload: {
            type: 'telemetry',
            deviceId: 'esp32-semaforo-01',
            timestamp: ts,
            light: { state: mem.light, remainingS: mem.remainingS, durationS: mem.durationS },
            mode,
            sensors: {
                ultrasonicCm: Math.round(mem.distanceCm * 10) / 10,
                vehicleDetected: mem.vehicleDetected,
                pedestrianRequest: mem.pedestrianRequest,
            },
            flow: { vehicleCount: (flow.get('totalBanco') || 0) + mem.sessionCount, vehiclesPerMin },
            actuators: { ledRed: mem.light === 'RED', ledYellow: mem.light === 'YELLOW', ledGreen: mem.light === 'GREEN' },
            device: { online: mem.online, wifiRssi: mem.wifiRssi, uptimeS: mem.uptimeS },
            alerts,
        },
    };
}
return [telemetry, command, db.length ? db : null];

const n = parseInt(msg.req.query.limite, 10);
msg.params = { $limite: Number.isFinite(n) && n > 0 ? Math.min(n, 50) : 8 };
return msg;

const n = parseInt(msg.req.query.limite, 10);
msg.params = { $limite: Number.isFinite(n) && n > 0 ? Math.min(n, 720) : 60 };
return msg;

// Mais antigo primeiro, para o gráfico
msg.payload = (msg.payload || []).reverse();
return msg;

msg.statusCode = 500;
msg.payload = { erro: msg.error && msg.error.message ? msg.error.message : 'erro no banco' };
return msg;
